export const DetailEntrySchema = z.object({
  id: z.string(),
  provider_id: z.string(),
  author: z.string().nullable(),
  title: z.string().nullable(),
  state: z.string().nullable(),
  body: DetailValueSchema,
  observed_body_state: DetailValueStateSchema,
  updated_at: z.string().nullable(),
  head_oid: z.string().nullable(),
  native: NativeDetailPayloadSchema.nullable(),
  field_mask: z.array(DetailFieldSchema),
  field_validations: z.array(DetailFieldValidationSchema),
}).superRefine((entry, context) => {
  const family = detailFieldFamilies[entry.native?.kind ?? "generic"];
  const mask = new Set<string>(entry.field_mask);
  const validations = entry.field_validations.map((validation) => validation.field);
  const validated = new Set<string>(validations);
  const exactNativeEvidence = entry.native?.kind === "check.v1" || entry.native?.kind === "review.v1" || entry.native?.kind === "review_thread.v1";
  const invalidExactEvidence = exactNativeEvidence && (mask.size !== family.size || validated.size !== family.size || [...family].some((field) => !mask.has(field) || !validated.has(field)));
  if (invalidExactEvidence || entry.field_mask.length > family.size || validations.length > family.size || mask.size !== entry.field_mask.length || validated.size !== validations.length || entry.field_mask.some((field) => !family.has(field)) || validations.some((field) => !family.has(field))) {
    context.addIssue({ code: "custom", path: ["native"], message: "Detail entry fields do not match its native payload" });
  }
});

